-- Private G equipment lifecycle. Logical pieces remain backed by exactly one entity.
create or replace function ml_private.p3g_equipment_actions(s jsonb,a integer,free boolean,blocked boolean) returns jsonb language plpgsql stable set search_path=pg_catalog,ml_private as $$declare bread jsonb:='[]';watch jsonb:='[]';terrain jsonb:='[]';card text;record jsonb;begin
 if not ml_private.p3g_enabled(s) then return '{}';end if;
 if free then select coalesce(jsonb_agg(v order by n),'[]') into bread from jsonb_array_elements(ml_private.p3g_combat_gears(s,a,'basic-054')) with ordinality q(v,n) where (s#>>array['stage3','starts',a::text])::int>=coalesce((s#>>array['stage3','g','gearBreadReadyAt',v#>>'{}'])::int,0);end if;
 if free and not blocked then for card in select v#>>'{}' from ml_private.arr(ml_private.p3g_combat_gears(s,a,'basic-060')) v loop record:=s#>array['stage4','watches',card];if record->>'previous' is not null and record->'usedTurn' is distinct from s#>'{stage3,turn}' and record->>'previous'<>s#>>array['players',a::text,'cell'] and ml_private.stage4_board_empty(s,a,record->>'previous',jsonb_build_array(a)) then watch:=watch||jsonb_build_array(jsonb_build_object('card',card,'cell',record->'previous'));end if;end loop;end if;
 if ml_private.stage4_on_board(s,a) then select coalesce(jsonb_agg(jsonb_build_object('card',v,'ignored',coalesce(s#>>array['stage3','g','gearTerrain',v#>>'{}'],'false')='true') order by n),'[]') into terrain from jsonb_array_elements(ml_private.p3g_combat_gears(s,a,'basic-069')) with ordinality q(v,n);end if;
 return jsonb_build_object('equipmentSkills',jsonb_build_object('bread',bread,'watch',watch,'terrain',terrain));
end $$;
create or replace function ml_private.p3g_combat_gears(s jsonb,a integer,definition text) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select coalesce(jsonb_agg(v order by n),'[]') from jsonb_array_elements(s#>array['stage3','equipment',a::text]) with ordinality q(v,n) where ml_private.stage4_equipment_definition(s,v#>>'{}')=definition and ml_private.stage3_card_allowed(s,a,v#>>'{}',(s#>array['stage3','equipmentSources',v#>>'{}'])||jsonb_build_object('origin','equipment'))$$;
create or replace function ml_private.p3g_card_range(s jsonb,a integer,d jsonb,cell text) returns boolean language plpgsql stable set search_path=pg_catalog,ml_private as $$declare origin text:=ml_private.region_at(s->>'version',s#>>array['players',a::text,'cell']);dest text:=ml_private.region_at(s->>'version',cell);reached jsonb:=jsonb_build_array(origin);regions jsonb;bonus integer:=jsonb_array_length(ml_private.p3g_combat_gears(s,a,'basic-058'));i integer;begin
 if ml_private.p3c_feather(s,a) and d->>'type'='attack' or d->>'range'='global' or origin=dest then return true;end if;
 for i in 1..bonus+case when d->>'range'='adjacent' then 1 else 0 end loop select coalesce(jsonb_agg(key order by key),'[]') into regions from jsonb_object_keys(ml_private.version_catalog(s->>'version')#>'{mapDefinition,regions}') key where reached ? key or exists(select 1 from ml_private.arr(reached) v where ml_private.neighbor_for_version(s->>'version',v#>>'{}',key));reached:=regions;end loop;return reached ? dest;
end $$;
create or replace function ml_private.p3g_after_damage(s jsonb,hits jsonb,environment boolean) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare tasks jsonb:='[]';root text:=coalesce(s#>>'{cardStack,stack,0,serial}','batch'||(s->>'batch'));h jsonb;a integer;target integer;owner integer;victim integer;pair jsonb;gear text;paid integer;attack jsonb;begin
 for h in select * from ml_private.arr(hits) loop a:=(h->>'source')::int;target:=(h->>'target')::int;
  if a is not null and a<>target then for pair in select * from ml_private.arr(jsonb_build_array(jsonb_build_array(a,target),jsonb_build_array(target,a))) loop owner:=(pair->>0)::int;victim:=(pair->>1)::int;if not ml_private.stage4_on_board(s,owner) or not ml_private.stage4_on_board(s,victim) then continue;end if;
   for gear in select v#>>'{}' from ml_private.arr(ml_private.p3g_combat_gears(s,owner,'basic-055')) v loop if not ml_private.stage4_gear_permitted(s,owner,victim,gear) then continue;end if;s:=ml_private.stage4_gear_mark(s,root||':sugar:'||owner||':'||victim||':'||gear);if s->>'_marked'='true' then paid:=least(1,(s#>>array['players',victim::text,'ap'])::int);s:=jsonb_set(s,array['players',victim::text,'ap'],to_jsonb((s#>>array['players',victim::text,'ap'])::int-paid));s:=ml_private.emit(s,'ap','S'||(owner+1)||' 冰糖雪梨扣S'||(victim+1)||' '||paid||'AP');end if;s:=s-'_marked';end loop;
  end loop;end if;
  if ml_private.stage4_on_board(s,target) and not environment and coalesce(h->>'reflected','false')<>'true' and a is not null and a<>target and ml_private.stage4_on_board(s,a) then for gear in select v#>>'{}' from ml_private.arr(ml_private.p3g_combat_gears(s,target,'basic-051')) v loop if ml_private.stage4_gear_permitted(s,target,a,gear) then tasks:=tasks||jsonb_build_array(ml_private.stage3_task('gear-reflect',jsonb_build_object('actor',target,'target',a,'card',gear)));end if;end loop;end if;
  if a is null or a=target or not ml_private.stage4_on_board(s,a) or not ml_private.stage4_on_board(s,target) then continue;end if;attack:=ml_private.stage4_card_attack(s,h);
  if attack is not null and coalesce(h->>'extra','false')<>'true' then
   for gear in select v#>>'{}' from ml_private.arr(ml_private.p3g_combat_gears(s,a,'basic-052')) v loop if (s#>>array['players',a::text,'ap'])::int>=1 and ml_private.stage4_gear_permitted(s,a,target,gear) then s:=ml_private.stage4_gear_mark(s,root||':chalk:'||a||':'||gear);if s->>'_marked'='true' then tasks:=tasks||jsonb_build_array(ml_private.stage3_task('gear-chalk',jsonb_build_object('actor',a,'target',target,'card',gear)));end if;s:=s-'_marked';end if;end loop;
   for gear in select v#>>'{}' from ml_private.arr(ml_private.p3g_combat_gears(s,a,'basic-062')) v loop if ml_private.stage4_gear_permitted(s,a,target,gear) then s:=jsonb_set(s,array['stage4','tongPending',target::text],ml_private.stage4_gear_source(s,a,gear));s:=ml_private.emit(s,'buff','S'||(target+1)||' 下个个人回合不能主动位移');end if;end loop;
  end if;
  for gear in select v#>>'{}' from ml_private.arr(ml_private.p3g_combat_gears(s,a,'basic-061')) v loop if ml_private.stage4_gear_permitted(s,a,target,gear) and coalesce(h->>'extra','false')<>'true' then s:=ml_private.stage4_gear_mark(s,root||':plant:'||a||':'||target||':'||gear);if s->>'_marked'='true' then tasks:=tasks||jsonb_build_array(ml_private.stage3_task('gear-plant',jsonb_build_object('actor',a,'target',target,'card',gear)));end if;s:=s-'_marked';end if;end loop;
 end loop;return s||jsonb_build_object('_gearTriggers',tasks||ml_private.stage4_reactive_injury(s,hits));
end $$;
create or replace function ml_private.p3g_terrain_refresh(s jsonb,a integer) returns jsonb language sql stable set search_path=pg_catalog,ml_private as $$select case when ml_private.p3g_enabled(s) then jsonb_set(s,array['stage4','terrainIgnore',a::text],to_jsonb(exists(select 1 from ml_private.arr(s#>array['stage3','equipment',a::text]) v where ml_private.stage4_equipment_definition(s,v#>>'{}')='basic-069' and s#>>array['stage3','g','gearTerrain',v#>>'{}']='true'))) else s end$$;
create or replace function ml_private.p3g_equipment_valid(s jsonb) returns boolean language plpgsql stable set search_path=pg_catalog,ml_private as $$declare pieces jsonb;outside jsonb;physical text;pair jsonb;part text;a integer;gear text;slot text;slots jsonb;names jsonb;n integer;begin
 if not ml_private.p3g_enabled(s) then return true;end if;if jsonb_typeof(s#>'{stage3,g,pairs}') is distinct from 'object' then return false;end if;
 pieces:='[]';outside:=(s->'deck')||(s->'discard');for a in 0..3 loop outside:=outside||(s#>array['players',a::text,'hand']);slots:='{}';names:='[]';for gear in select v#>>'{}' from ml_private.arr(s#>array['stage3','equipment',a::text]) v loop
  slot:=ml_private.rule_card(s,gear)->>'slot';if slot is null then return false;end if;n:=coalesce((slots->>slot)::int,0)+1;slots:=jsonb_set(slots,array[slot],to_jsonb(n));if n>(case when s#>>array['players',a::text,'character']='character-021' or slot='hand' then 2 else 1 end) or s#>>array['players',a::text,'character']<>'character-021' and names ? split_part(gear,'#',1) then return false;end if;names:=names||jsonb_build_array(split_part(gear,'#',1));if gear ~ '#[0-9]{2}~g[12]$' then pieces:=pieces||jsonb_build_array(gear);end if;
 end loop;end loop;
 for part in select v#>>'{}' from ml_private.arr(s->'resolving') v where v#>>'{}' ~ '#[0-9]{2}~g[12]$' loop pieces:=pieces||jsonb_build_array(part);end loop;
 if (select count(distinct v) from ml_private.arr(pieces) v)<>jsonb_array_length(pieces) or exists(select 1 from ml_private.arr(outside) v where v#>>'{}' ~ '#[0-9]{2}~g[12]$') then return false;end if;
 for part in select v#>>'{}' from ml_private.arr(pieces) v loop if ml_private.p3g_piece_physical(s,part) is null then return false;end if;end loop;
 for physical,pair in select key,value from jsonb_each(s#>'{stage3,g,pairs}') loop
  if jsonb_typeof(pair->'open') is distinct from 'boolean' or pair->'parts' is distinct from jsonb_build_array(physical||'~g1',physical||'~g2') or jsonb_typeof(pair->'removed') is distinct from 'array' then return false;end if;
  if (select count(distinct v) from ml_private.arr(pair->'removed') v)<>jsonb_array_length(pair->'removed') or not((pair->'parts') @> (pair->'removed')) then return false;end if;
  if (pair->>'open'='true') is distinct from ((s->'resolving') ? physical) then return false;end if;
  for part in select v#>>'{}' from ml_private.arr(pair->'parts') v loop if pair->'removed' ? part then if pieces ? part then return false;end if;elsif pair->>'open'='false' and not(pieces ? part) then return false;end if;end loop;
 end loop;return true;
end $$;
create or replace function ml_private.p3g_equipment_zones(s jsonb,zones jsonb) returns jsonb language sql immutable set search_path=pg_catalog,ml_private as $$select case when not ml_private.p3g_enabled(s) then zones else (select coalesce(jsonb_agg(v order by ord),'[]') from jsonb_array_elements(zones) with ordinality q(v,ord) where ml_private.p3g_piece_physical(s,v#>>'{}') is null)||(select coalesce(jsonb_agg(key order by key),'[]') from jsonb_each(s#>'{stage3,g,pairs}') p where p.value->>'open'='false') end$$;
create or replace function ml_private.p3g_equipment_task(s jsonb,t jsonb,at double precision) returns jsonb language plpgsql volatile set search_path=pg_catalog,ml_private as $$declare action text:=t->>'action';a integer:=coalesce((t->>'actor')::int,(s->>'active')::int);data jsonb:=t->'data';g jsonb;c jsonb;options jsonb;replacement text;old jsonb;target integer;tasks jsonb:='[]';idx text;begin
 if not ml_private.p3g_enabled(s) then return s||jsonb_build_object('_gEquipmentHandled',false);end if;
 if action='g-paired-transfer' then
  g:=data->'gear';if not ml_private.stage4_on_board(s,a) or not(s#>array['stage3','equipment',data->>'source'] ? (g->>'card')) then return s||jsonb_build_object('_gEquipmentHandled',true);end if;options:=ml_private.stage3_equipment_options(s,a,g->>'card');
  if options->>'allowed'<>'true' or g->>'definition' in ('basic-063','basic-064') and ml_private.stage4_board_water(s,s#>>array['players',a::text,'cell'],a) or options->>'required'='true' and (data->>'replacement' is null or data->>'replaced'='true' or not(options->'cards' ? (data->>'replacement'))) then return ml_private.emit(s,'transfer','成对装备件无法合法安装，留在原装备区')||jsonb_build_object('_gEquipmentHandled',true);end if;
  if options->>'required'='true' then old:=ml_private.stage4_gear_snapshot(s,a,data->>'replacement');s:=ml_private.stage4_gear_detach(s,a,old,true);s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('gear-loss',jsonb_build_object('actor',a,'data',old)),ml_private.stage3_task(action,jsonb_build_object('actor',a,'data',data||jsonb_build_object('replaced',true)))));
  else s:=ml_private.stage4_gear_detach(s,(data->>'source')::int,g,false);s:=ml_private.stage4_gear_install(s,a,g);s:=ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('gear-loss',jsonb_build_object('actor',data->'source','data',g))));s:=ml_private.emit(s,'transfer','S'||(a+1)||' 成对装备件只转入装备区');end if;return s||jsonb_build_object('_gEquipmentHandled',true);
 end if;
 c:=s#>'{cardStack,stack,-1}';if action='effect' and c->>'definition'='basic-024' and c#>>'{stage4,take}'='equipment' and ml_private.p3g_piece_physical(s,c#>>'{stage4,item}') is not null then
  a:=(c->>'actor')::int;s:=ml_private.stage3_record_combo(s,a,c->>'definition');select (v#>>'{}')::int into target from ml_private.arr(ml_private.stage4_map_targets(s,c)) v limit 1;
  if target is not null and s#>array['stage3','equipment',target::text] ? (c#>>'{stage4,item}') then g:=ml_private.stage4_gear_snapshot(s,target,c#>>'{stage4,item}');tasks:=jsonb_build_array(ml_private.stage3_task('g-paired-transfer',jsonb_build_object('actor',a,'data',jsonb_build_object('source',target,'gear',g)||case when c ? 'replacement' then jsonb_build_object('replacement',c->'replacement') else '{}'::jsonb end)));end if;
  return ml_private.stage3_prepend(s,tasks||jsonb_build_array(ml_private.stage3_task('cleanup',jsonb_build_object('serial',c->'serial'))))||jsonb_build_object('_gEquipmentHandled',true);
 end if;
 if c->'g' is null or ml_private.rule_card(s,c->>'definition')->>'type'<>'equipment' then return s||jsonb_build_object('_gEquipmentHandled',false);end if;a:=(c->>'actor')::int;
 if action='equip-install' then if ml_private.stage4_on_board(s,a) then g:=jsonb_build_object('card',(c->>'card')||'~g'||(c#>>'{g,copy}'),'definition',coalesce(c#>>'{stage4,copy}',split_part(c->>'card','#',1)),'effect',c->'effect');if ml_private.stage4_can_install(s,a,g) then s:=ml_private.stage4_gear_install(s,a,g);idx:=(jsonb_array_length(s#>'{cardStack,stack}')-1)::text;s:=jsonb_set(s,array['cardStack','stack',idx,'installed'],'true');end if;end if;return s||jsonb_build_object('_gEquipmentHandled',true);end if;
 if action<>'effect' then return s||jsonb_build_object('_gEquipmentHandled',false);end if;s:=ml_private.stage3_record_combo(s,a,c->>'definition');
 if ml_private.stage4_on_board(s,a) and ml_private.stage3_card_allowed(s,a,c->>'definition',c->'effect') then options:=ml_private.stage3_equipment_options(s,a,c->>'card');if options->>'required'='true' then select v#>>'{}' into replacement from jsonb_array_elements(coalesce(c#>'{g,replacements}','[]')) with ordinality q(v,n) where s#>array['stage3','equipment',a::text] ? (v#>>'{}') and options->'cards' ? (v#>>'{}') order by n limit 1;end if;
  if options->>'allowed'<>'true' or options->>'required'='true' and replacement is null or coalesce(c#>>'{stage4,copy}',c->>'definition') in ('basic-063','basic-064') and ml_private.stage4_board_water(s,s#>>array['players',a::text,'cell'],a) then return ml_private.stage3_prepend(s,jsonb_build_array(ml_private.stage3_task('cleanup',jsonb_build_object('serial',c->'serial'))))||jsonb_build_object('_gEquipmentHandled',true);end if;
  if replacement is not null then old:=ml_private.stage4_gear_snapshot(s,a,replacement);s:=ml_private.stage4_gear_detach(s,a,old,true);tasks:=tasks||jsonb_build_array(ml_private.stage3_task('gear-loss',jsonb_build_object('actor',a,'data',old)));end if;tasks:=tasks||jsonb_build_array(ml_private.stage3_task('equip-install',jsonb_build_object('serial',c->'serial')));
 end if;return ml_private.stage3_prepend(s,tasks||jsonb_build_array(ml_private.stage3_task('cleanup',jsonb_build_object('serial',c->'serial'))))||jsonb_build_object('_gEquipmentHandled',true);
end $$;
